for i,(g,o) in enumerate(examples):
 print('\n',i+1)
 cc=comps(g)
 for pts in sorted(cc,key=len, reverse=True):
  colors={o[r][c] for r,c in pts}
  bbox=(min(r for r,c in pts),max(r for r,c in pts),min(c for r,c in pts),max(c for r,c in pts))
  print(len(pts), next(iter(colors)) if len(colors)==1 else colors, bbox, 'borders',sum(r==0 for r,c in pts),sum(r==len(g)-1 for r,c in pts),sum(c==0 for r,c in pts),sum(c==len(g[0])-1 for r,c in pts))
